package probe

import (
 "context"
 "testing"
 "go.opentelemetry.io/otel/attribute"
 "go.opentelemetry.io/otel/sdk/resource"
 sdktrace "go.opentelemetry.io/otel/sdk/trace"
 "go.opentelemetry.io/otel/sdk/trace/tracetest"
)

// Same resource.New and WithResource calls as chi-partial's initTracing.
// The independent in-memory sink makes this a configuration probe, not OTLP proof.
func TestExplicitResourceStillMergesEnvironment(t *testing.T) {
 t.Setenv("OTEL_SERVICE_NAME", "independent-resource-probe")
 t.Setenv("OTEL_RESOURCE_ATTRIBUTES", "service.version=frozen-probe,deployment.environment.name=demo")
 r,err:=resource.New(context.Background());if err!=nil{t.Fatal(err)}
 if len(r.Attributes())!=0{t.Fatal("source resource should be empty before SDK merge")}
 sink:=tracetest.NewInMemoryExporter()
 tp:=sdktrace.NewTracerProvider(sdktrace.WithResource(r),sdktrace.WithSyncer(sink))
 defer tp.Shutdown(context.Background())
 _,span:=tp.Tracer("source-config-probe").Start(context.Background(),"resource construction probe");span.End()
 spans:=sink.GetSpans();if len(spans)!=1{t.Fatalf("captured %d",len(spans))}
 for k,want:=range map[string]string{"service.name":"independent-resource-probe","service.version":"frozen-probe","deployment.environment.name":"demo"}{got,ok:=spans[0].Resource.Set().Value(attribute.Key(k));if !ok||got.AsString()!=want{t.Fatalf("%s=%v wanted %s",k,got,want)};t.Logf("%s=%s",k,got.AsString())}
}
